// 生产者（spring-kafka）
// application.yml:
//   spring.kafka.producer.acks: all
//   spring.kafka.producer.retries: 3
//   spring.kafka.producer.properties.enable.idempotence: true
//   spring.kafka.consumer.enable-auto-commit: false
//   spring.kafka.listener.ack-mode: manual
kafkaTemplate.send("order-paid", orderNo, payload)
        .whenComplete((result, ex) -> {
            if (ex != null) {
                log.error("send failed, orderNo={}", orderNo, ex);
                outboxService.markRetry(orderNo);      // 落库，定时任务补发
            }
        });

// 消费者：处理成功后再提交
@KafkaListener(topics = "order-paid", groupId = "points")
public void onMessage(ConsumerRecord<String, String> rec, Acknowledgment ack) {
    pointsService.addPointsIdempotent(rec.key(), rec.value());   // 幂等处理
    ack.acknowledge();
}

@Transactional(rollbackFor = Exception.class)
public void addPointsIdempotent(String orderNo, String payload) {
    try {
        // 去重表 consume_log(biz_key) 有唯一索引，与业务在同一事务
        consumeLogMapper.insert(new ConsumeLog("points:" + orderNo));
    } catch (DuplicateKeyException e) {
        log.info("duplicate message, skip orderNo={}", orderNo);
        return;
    }
    PaidEvent ev = JSON.parseObject(payload, PaidEvent.class);
    pointsMapper.add(ev.userId(), ev.amount() / 100);
}

-- 状态机方式
UPDATE t_order SET status = 'PAID', paid_time = NOW()
 WHERE order_no = ? AND status = 'UNPAID';   -- 影响 0 行则说明已处理

-- 去重表
CREATE TABLE mq_consume_record (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  consumer_group VARCHAR(64) NOT NULL,
  biz_key VARCHAR(128) NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_group_key (consumer_group, biz_key)
);

-- 消费逻辑（同一事务内）
BEGIN;
INSERT INTO mq_consume_record(consumer_group, biz_key) VALUES ('points', 'PAID:O20261031001');
-- 若唯一键冲突 → 回滚并直接 ACK（已处理过）
UPDATE user_points SET points = points + 100 WHERE user_id = 42;
COMMIT;

-- 状态机方式
UPDATE t_coupon SET status = 'USED', used_order = 'O20261031001'
 WHERE id = 7 AND status = 'UNUSED';   -- 影响行数 0 → 已处理

